-- The move-in total, computed from its own parts rather than typed.
--
-- `listings_total_move_in_covers_its_parts` requires the total to be at least
-- the sum of the rent, the caution deposit and the three fees. Deriving it here
-- rather than writing forty-two arithmetic results by hand means the constraint
-- cannot be tripped by a typo, and means the figure a reader sees is exactly the
-- figure the components add up to, which is the whole point of P-2.
update public.listings
   set total_move_in_cost_minor =
         coalesce(rent_amount_minor, 0)
       + coalesce(caution_deposit_minor, 0)
       + coalesce(agency_fee_minor, 0)
       + coalesce(legal_fee_minor, 0)
       + coalesce(agreement_fee_minor, 0)
 where is_demo = true
   and listing_intent = 'rent'
   and rent_amount_minor is not null;
